(3, 'IN|KA|Udupi|Ambalpadi', 'Ambalpadi', 'ambalpadi', '2575_missing_area_onboarding', now()),
(1, 'IN|KA|Bengaluru|Adinarayana Hosahalli', 'Adinarayana Hosahalli', 'adinarayana hosahalli', '2575_missing_area_onboarding', now())
ON CONFLICT (city_id, alias_normalised) DO NOTHING;

-- 4. Update Housing commercial listings for new canonical areas
CREATE TEMP TABLE temp_area_updates (
    listing_id uuid PRIMARY KEY,
    target_area_key text,
    target_area_label text
) ON COMMIT DROP;


UPDATE public.property_listings pl
SET
    area_key = tau.target_area_key,
    area_label = tau.target_area_label,
    area_resolution_status = 'RESOLVED',
    area_resolution_method = 'NEW_CANONICAL_AREA',
    updated_at = now()
FROM temp_area_updates tau
WHERE pl.id = tau.listing_id;

-- 5. Classify out-of-scope / malformed listings
CREATE TEMP TABLE temp_invalid_updates (
    listing_id uuid PRIMARY KEY,
    reason_text text
) ON COMMIT DROP;


UPDATE public.property_listings pl
SET
    area_resolution_status = 'UNRESOLVED',
    area_resolution_method = 'INVALID_OR_OUT_OF_SCOPE',
    rejection_reason = tiu.reason_text,
    updated_at = now()
FROM temp_invalid_updates tiu
WHERE pl.id = tiu.listing_id;

COMMIT;
